#include "midi_controller.hpp"
static void midiControllerTests(){
    using A=ControlAction;using P=ControllerProfile;ControllerDecoder decoder;
    check(detectController(L"KL Essential 49 mk3 MCU/HUI")==P::Arturia,"Arturia Essential MCU name detected");check(detectController(L"Launchkey 61 MK3 DAW")==P::Launchkey3,"Launchkey MK3 DAW name detected");check(detectController(L"Launchkey Mini MK3")==P::Generic,"Mini does not receive a larger Launchkey mapping");check(detectController(L"Launchkey 49 MK4")==P::Generic,"MK4 does not inherit an incompatible MK3 map");check(detectController(L"MPK mini 3")==P::Akai&&detectController(L"Komplete Kontrol")==P::Native,"Akai and NI family identification");
    auto message=[](int s,int n,int v){return(uint32_t)(s|(n<<8)|(v<<16));};
    auto play=message(0x90,94,127);check(decoder.decode(P::Arturia,play,{}).action==A::Play,"MCU play press");check(decoder.decode(P::Arturia,play,{}).action==A::None,"Held transport button does not toggle repeatedly");decoder.decode(P::Arturia,message(0x80,94,0),{});check(decoder.decode(P::Arturia,play,{}).action==A::Play,"Note Off rearms transport");
    check(decoder.decode(P::Mackie,message(0xe7,127,127),{}).index==7,"Ninth MIDI channel is not confused with master");auto master=decoder.decode(P::Mackie,message(0xe8,0,64),{});check(master.action==A::Volume&&master.index==8&&std::abs(master.value-8192./16383)<1e-9,"14-bit Master fader");check(decoder.decode(P::Mackie,message(0xb0,16,65),{}).value==-1,"MCU signed relative pan");decoder.decode(P::Mackie,message(0x90,104,127),{});check(decoder.touched[0],"MCU fader touch suppresses motor feedback");decoder.decode(P::Mackie,message(0x90,104,0),{});check(!decoder.touched[0],"MCU fader release");
    decoder.reset();check(decoder.decode(P::Launchkey3,message(0xbf,115,127),{}).action==A::Play,"Documented Launchkey Play CC115");check(decoder.decode(P::Launchkey3,message(0xbf,76,127),{}).action==A::Click,"Documented Launchkey Click CC76");check(decoder.decode(P::Launchkey3,message(0xbf,102,127),{}).action==A::PreviousTrack,"Launchkey Track Left CC102");check(decoder.decode(P::Launchkey3,message(0xbf,61,127),{}).index==8,"Launchkey ninth fader controls Master");decoder.decode(P::Launchkey3,message(0xbf,9,2),{});check(decoder.decode(P::Launchkey3,message(0xbf,21,64),{}).action==A::Plugin,"Launchkey Device mode changes knobs to plugin parameters");decoder.decode(P::Launchkey3,message(0xbf,9,3),{});check(decoder.decode(P::Launchkey3,message(0xbf,21,64),{}).action==A::Pan,"Launchkey Pan mode");check(decoder.decode(P::Launchkey3,message(0xb0,21,64),{}).action==A::None,"Launchkey DAW CC map never steals musical-channel CC");
    std::vector<MidiBinding>bindings={{0xb2,0,1,0,A::Volume,-1}};check(readBindings(bindingsJson(bindings)).empty(),"Invalid status is rejected");bindings={{0xb0,2,71,2,A::Plugin,3},{0x90,1,42,0,A::Record,-1}};auto restored=readBindings(bindingsJson(bindings));check(restored.size()==2&&restored[0].index==3,"Learned bindings round-trip");decoder.reset();auto learned=decoder.decode(P::Generic,message(0xb2,71,127),restored);check(learned.action==A::Plugin&&learned.relative&&learned.value==-1,"Learned two-complement encoder");check(decoder.decode(P::Generic,message(0xb1,71,127),restored).action==A::None,"MIDI Learn is channel-specific");check(readBindings(Json::object()).empty()&&readBindings(Json::array({42,{{"status",false}}})).empty(),"Malformed mappings recover safely");
    SoftPickup pickup;check(!pickup.accept(.9,.5)&&!pickup.accept(.8,.5)&&pickup.accept(.4,.5),"Soft takeover waits until crossing the DAW value");check(pickup.accept(.45,.4)&&!pickup.accept(.45,.8),"External changes relatch soft takeover");check(relativeMidi(62,3)==-2&&relativeMidi(66,3)==2&&relativeMidi(15,4)==-1,"Arturia relative encoder formats");
    Project p;p.tracks.resize(1);auto plan=compile(p);auto r=std::make_unique<Renderer>();std::array<float,1024>out{};auto render=[&](){r->render(*plan,out.data(),512,false);double energy=0;for(auto v:out)energy+=v*v;return energy;};render();r->live(*plan,{message(0x90,60,100),0});render();r->live(*plan,{message(0xb0,64,127),0});r->live(*plan,{message(0x80,60,0),0});for(int i=0;i<150;i++)render();check(render()>.01,"Sustain holds built-in instrument after key release");r->live(*plan,{message(0xb0,64,0),0});for(int i=0;i<500;i++)render();check(render()<1e-8,"Pedal release ends sustained voices");
    auto fixture=std::make_shared<Plugin>();std::string error;check(fixture->load(L"build/midi-fixture.vst3",48000,error),error.c_str());check(fixture->instrument()&&fixture->acceptsNotes(),"MIDI fixture exposes instrument and controller interfaces");std::array<float,64>left{},right{};auto process=[&](){fixture->process(left.data(),right.data(),64,nullptr,0,0,120,false);return left[0];};
    fixture->midiMessage(message(0xb2,1,127));check(std::abs(process()-.1)<1e-6,"VST3 modwheel reaches the processor through IMidiMapping");fixture->midiMessage(message(0xb2,64,127));check(std::abs(process()-.3)<1e-6,"VST3 sustain controller");fixture->midiMessage(message(0xe2,127,127));check(std::abs(process()-.6)<1e-6,"VST3 14-bit pitch bend");fixture->midiMessage(message(0xd2,127,0));check(std::abs(process()-.75)<1e-6,"VST3 channel pressure uses its data byte");fixture->midiMessage(message(0xa2,60,127));check(std::abs(process()-.85)<1e-6,"VST3 polyphonic aftertouch event");fixture->midiMessage(message(0xb0,1,0));check(std::abs(process()-.85)<1e-6,"MIDI controller channel mapping is respected");check(fixture->setParameter(5,1)&&std::abs(process()-.9)<1e-6,"Learned plugin parameter reaches processor and controller");check(std::abs(fixture->parameterValue(5)-1)<1e-9,"Plugin parameter readback for soft takeover");
    PluginRack rack;rack[0]={fixture};auto routed=compile(p,rack);auto live=std::make_unique<Renderer>();live->render(*routed,out.data(),512,false);live->live(*routed,{message(0xb2,1,0),0});live->render(*routed,out.data(),512,false);check(std::abs(fixture->parameterValue(0))<1e-9,"Renderer forwards live CC to VST3 rather than dropping it");
    std::ofstream(L"work/test-results/midi-controllers.json")<<Json({{"passed",true},{"mcu_transport_faders_touch",true},{"launchkey_documented_cc",true},{"profile_version_isolation",true},{"learn_round_trip",true},{"relative_encoders",true},{"soft_takeover",true},{"builtin_sustain",true},{"vst3_midi_mapping_processing",true},{"vst3_plugin_parameter_processing",true},{"physical_hardware_tested",false}}).dump(2);
}
